import sys, csv
from io import StringIO
try:
    reader = csv.DictReader(StringIO(sys.stdin.read()), strict=True)
    rows = list(reader)
except csv.Error:
    raise SystemExit(1)
if reader.fieldnames != ["name"] or any(set(row) != {"name"} or row["name"] is None or not row["name"].strip() for row in rows):
    raise SystemExit(1)
