import sys, csv
from io import StringIO
try:
    reader = csv.DictReader(StringIO(sys.stdin.read()), strict=True)
    rows = list(reader)
except csv.Error:
    raise SystemExit(1)
if reader.fieldnames != ["count"] or any(set(row) != {"count"} or row["count"] is None for row in rows):
    raise SystemExit(1)
try:
    counts = [int(row["count"]) for row in rows]
except ValueError:
    raise SystemExit(1)
if any(value < 0 for value in counts):
    raise SystemExit(1)
# 完成本课操作与输出

